diff --git a/repro/emfile-fix-check.js b/repro/emfile-fix-check.js
new file mode 100644
index 0000000..e989138
--- /dev/null
+++ b/repro/emfile-fix-check.js
@@ -0,0 +1,94 @@
+#!/usr/bin/env node
+/**
+ * Check for: "running `eslint ./ --fix` throws EMFILE: too many open files"
+ *
+ * Builds a throwaway project of N files that each have one auto-fixable
+ * problem (`no-var`), runs `eslint ./ --fix` on it with the CLI from this
+ * checkout, and asserts the expected behavior from the report: the command
+ * succeeds and every auto-fixable file is fixed.
+ *
+ * Exits non-zero while the bug is present, zero once it is fixed.
+ *
+ * Usage (from the repo root):
+ *   node repro/emfile-fix-check.js            # 3000 files under `ulimit -n 1024`
+ *   FILES=25000 NOFILE=default node repro/emfile-fix-check.js
+ *                                             # no lowered fd limit; needs more files
+ *                                             # than this machine's `ulimit -n`
+ *
+ * The report is from Windows, where Node/libuv caps open fds at about 8192.
+ * The default run lowers the soft fd limit instead (simulated), so it takes
+ * seconds rather than minutes. The NOFILE=default run uses the machine's own limit.
+ */
+"use strict";
+
+const fs = require("node:fs");
+const os = require("node:os");
+const path = require("node:path");
+const { spawnSync } = require("node:child_process");
+
+const files = Number(process.env.FILES || 3000);
+const nofile = process.env.NOFILE || "1024";
+const eslintBin = path.resolve(__dirname, "..", "bin", "eslint.js");
+const dirs = 50;
+
+const project = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-emfile-"));
+
+try {
+	fs.writeFileSync(
+		path.join(project, "eslint.config.js"),
+		'module.exports = [{ rules: { "no-var": "error" } }];\n',
+	);
+	for (let d = 0; d < dirs; d++) {
+		fs.mkdirSync(path.join(project, `d${d}`));
+	}
+	for (let i = 0; i < files; i++) {
+		fs.writeFileSync(
+			path.join(project, `d${i % dirs}`, `f${i}.js`),
+			"var a = 1;\nexport { a };\n",
+		);
+	}
+
+	const limit = nofile === "default" ? "" : `ulimit -n ${nofile} && `;
+	const result = spawnSync(
+		"sh",
+		["-c", `${limit}exec "${process.execPath}" "${eslintBin}" ./ --fix`],
+		{ cwd: project, encoding: "utf8", maxBuffer: 1 << 28 },
+	);
+
+	let unfixed = 0;
+	for (let i = 0; i < files; i++) {
+		const text = fs.readFileSync(
+			path.join(project, `d${i % dirs}`, `f${i}.js`),
+			"utf8",
+		);
+		if (text.startsWith("var ")) {
+			unfixed++;
+		}
+	}
+
+	const output = `${result.stdout}${result.stderr}`;
+	const failures = [];
+
+	if (result.status !== 0) {
+		failures.push(`eslint exited with status ${result.status}, expected 0`);
+	}
+	if (/EMFILE/u.test(output)) {
+		failures.push("output contains EMFILE");
+	}
+	if (unfixed > 0) {
+		failures.push(`${unfixed} of ${files} auto-fixable files were not fixed`);
+	}
+
+	if (failures.length > 0) {
+		console.error(output.trim().split("\n").slice(0, 12).join("\n"));
+		console.error(`\nFAIL (${files} files, nofile=${nofile}):`);
+		for (const failure of failures) {
+			console.error(`  - ${failure}`);
+		}
+		process.exitCode = 1;
+	} else {
+		console.log(`PASS (${files} files, nofile=${nofile}): all files fixed, exit 0`);
+	}
+} finally {
+	fs.rmSync(project, { recursive: true, force: true });
+}
